import java.util.*;

public class Main {
    public static void main(String[] args) {
        NatTable nat = new NatTable();

        String publicPortA = nat.translateOutbound("192.168.1.5", 49823, "8.8.8.8:443");
        System.out.println("Device A's outbound connection assigned public port " + publicPortA);

        String publicPortB = nat.translateOutbound("192.168.1.7", 51002, "1.1.1.1:443");
        System.out.println("Device B's outbound connection assigned public port " + publicPortB);

        String responseFor = nat.translateInbound(publicPortA);
        System.out.println("Response arrives for port " + publicPortA + ", forwarded to: " + responseFor);

        String unsolicited = nat.translateInbound("54999");
        System.out.println("Unsolicited inbound attempt on port 54999: " + unsolicited);
    }
}

// A simplified NAT table: outbound connections are assigned a public port and
// recorded, so a genuine response can be routed back to the right private
// device, while an unsolicited inbound packet with no matching entry is dropped.
class NatTable {
    private final Map<String, String> portToPrivateEndpoint = new HashMap<>();
    private int nextPublicPort = 54321;

    String translateOutbound(String privateIp, int privatePort, String destination) {
        String publicPort = String.valueOf(nextPublicPort++);
        portToPrivateEndpoint.put(publicPort, privateIp + ":" + privatePort);
        return publicPort;
    }

    String translateInbound(String publicPort) {
        String privateEndpoint = portToPrivateEndpoint.get(publicPort);
        if (privateEndpoint == null) {
            return "DROPPED, no NAT table entry exists for this port";
        }
        return privateEndpoint;
    }
}

