#include <iostream>
#include <string>
#include <unordered_map>
using namespace std;

// A simplified NAT table: outbound connections are assigned a public port and
// recorded, so a genuine response can be routed back to the right private
// device, while an unsolicited inbound packet with no matching entry is dropped.
class NatTable {
public:
    NatTable() : nextPublicPort(54321) {}

    string translateOutbound(const string& privateIp, int privatePort, const string& destination) {
        string publicPort = to_string(nextPublicPort++);
        portToPrivateEndpoint[publicPort] = privateIp + ":" + to_string(privatePort);
        return publicPort;
    }

    string translateInbound(const string& publicPort) {
        auto it = portToPrivateEndpoint.find(publicPort);
        if (it == portToPrivateEndpoint.end()) {
            return "DROPPED, no NAT table entry exists for this port";
        }
        return it->second;
    }

private:
    unordered_map<string, string> portToPrivateEndpoint;
    int nextPublicPort;
};

int main() {
    NatTable nat;

    string publicPortA = nat.translateOutbound("192.168.1.5", 49823, "8.8.8.8:443");
    cout << "Device A's outbound connection assigned public port " << publicPortA << endl;

    string publicPortB = nat.translateOutbound("192.168.1.7", 51002, "1.1.1.1:443");
    cout << "Device B's outbound connection assigned public port " << publicPortB << endl;

    string responseFor = nat.translateInbound(publicPortA);
    cout << "Response arrives for port " << publicPortA << ", forwarded to: " << responseFor << endl;

    string unsolicited = nat.translateInbound("54999");
    cout << "Unsolicited inbound attempt on port 54999: " << unsolicited << endl;

    return 0;
}
